CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260214095813_Init_Postgres') THEN
    CREATE TABLE "Roles" (
        "RoleId" integer GENERATED BY DEFAULT AS IDENTITY,
        "RoleName" character varying(100) NOT NULL,
        "Description" character varying(200),
        "RoleType" text,
        "IsActive" boolean NOT NULL,
        "CreatedDate" timestamp with time zone NOT NULL DEFAULT (now()),
        "CreatedBy" text NOT NULL,
        "UpdatedDate" timestamp with time zone,
        "UpdatedBy" text,
        CONSTRAINT "PK_Roles" PRIMARY KEY ("RoleId")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260214095813_Init_Postgres') THEN
    CREATE TABLE "UserStatuses" (
        "UserStatusId" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(50) NOT NULL,
        "Color" character varying(20) NOT NULL,
        "Description" character varying(1000),
        "IsActive" boolean NOT NULL,
        "AffectsAccess" boolean NOT NULL,
        "CreatedDate" timestamp with time zone NOT NULL DEFAULT (now()),
        "CreatedBy" text NOT NULL,
        "UpdatedDate" timestamp with time zone,
        "UpdatedBy" text,
        CONSTRAINT "PK_UserStatuses" PRIMARY KEY ("UserStatusId")
    );
    END IF;
END $EF$;

DO $EF$
