        "Email" character varying(255) NOT NULL,
        "RoleId" integer NOT NULL,
        "FirstName" character varying(100) NOT NULL,
        "LastName" character varying(100) NOT NULL,
        "MiddleName" character varying(100),
        "BirthDate" timestamp with time zone,
        "LastLoginDatetime" timestamp with time zone,
        "Gender" character varying(20),
        "BiologicalSex" integer,
        "MobileNumber" character varying(20),
        "Address" character varying(1000),
        "CreatedDate" timestamp with time zone NOT NULL DEFAULT (now()),
        "CreatedBy" text NOT NULL,
        "UpdatedDate" timestamp with time zone,
        "UpdatedBy" text,
        "UserStatusId" integer NOT NULL,
        "RequiredPasswordChange" boolean NOT NULL,
        CONSTRAINT "PK_Users" PRIMARY KEY ("UserId"),
        CONSTRAINT "FK_Users_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("RoleId") ON DELETE CASCADE,
        CONSTRAINT "FK_Users_UserStatuses_UserStatusId" FOREIGN KEY ("UserStatusId") REFERENCES "UserStatuses" ("UserStatusId") ON DELETE CASCADE
